/* Real EWMH integration test against the guest window manager. */
#include <X11/Xlib.h>
#include <X11/Xatom.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
static Display*d;static Window root;static int checks;
static void tick(void){XSync(d,False);usleep(250000);}
static void message(Window w,const char*name,long a,long b,long c){XEvent e={0};e.xclient.type=ClientMessage;e.xclient.window=w;e.xclient.message_type=XInternAtom(d,name,False);e.xclient.format=32;e.xclient.data.l[0]=a;e.xclient.data.l[1]=b;e.xclient.data.l[2]=c;XSendEvent(d,root,False,SubstructureRedirectMask|SubstructureNotifyMask,&e);tick();}
static int state(Window w,const char*name){Atom type;int fmt;unsigned long n,left;unsigned char*p=0;int yes=0;XGetWindowProperty(d,w,XInternAtom(d,"_NET_WM_STATE",False),0,128,False,XA_ATOM,&type,&fmt,&n,&left,&p);if(fmt==32)for(unsigned long i=0;i<n;i++)if(((unsigned long*)p)[i]==XInternAtom(d,name,False))yes=1;if(p)XFree(p);return yes;}
static void check(int ok,const char*s){printf("DESKTOP_WINDOW_TEST: %s %s\n",s,ok?"PASS":"FAIL");fflush(stdout);if(!ok)exit(1);checks++;}
int main(int argc,char**argv){if(argc!=2)return 2;d=XOpenDisplay(0);if(!d)return 3;root=DefaultRootWindow(d);Window a=XCreateSimpleWindow(d,root,60,70,240,150,1,0x67bfea,0x162e48),b=XCreateSimpleWindow(d,root,550,70,240,150,1,0x67bfea,0x28483c);Atom delete=XInternAtom(d,"WM_DELETE_WINDOW",False);XSetWMProtocols(d,a,&delete,1);XStoreName(d,a,"LinuxRunner Window One");XStoreName(d,b,"LinuxRunner Window Two");XSelectInput(d,a,ExposureMask|KeyPressMask|ButtonPressMask);XSelectInput(d,b,ExposureMask);XMapWindow(d,a);XMapWindow(d,b);tick();XWindowAttributes at;XGetWindowAttributes(d,a,&at);check(at.map_state==IsViewable,"first-window");XGetWindowAttributes(d,b,&at);check(at.map_state==IsViewable,"second-window");
Window focused;int revert;message(b,"_NET_ACTIVE_WINDOW",2,CurrentTime,0);XGetInputFocus(d,&focused,&revert);check(focused==b,"focus-second");message(a,"_NET_ACTIVE_WINDOW",2,CurrentTime,0);XGetInputFocus(d,&focused,&revert);check(focused==a,"focus-first");
message(a,"_NET_WM_STATE",1,XInternAtom(d,"_NET_WM_STATE_MAXIMIZED_VERT",False),XInternAtom(d,"_NET_WM_STATE_MAXIMIZED_HORZ",False));check(state(a,"_NET_WM_STATE_MAXIMIZED_VERT"),"maximize");message(a,"_NET_WM_STATE",0,XInternAtom(d,"_NET_WM_STATE_MAXIMIZED_VERT",False),XInternAtom(d,"_NET_WM_STATE_MAXIMIZED_HORZ",False));check(!state(a,"_NET_WM_STATE_MAXIMIZED_VERT"),"unmaximize");
message(a,"_NET_WM_STATE",1,XInternAtom(d,"_NET_WM_STATE_FULLSCREEN",False),0);check(state(a,"_NET_WM_STATE_FULLSCREEN"),"fullscreen");message(a,"_NET_WM_STATE",0,XInternAtom(d,"_NET_WM_STATE_FULLSCREEN",False),0);check(!state(a,"_NET_WM_STATE_FULLSCREEN"),"fullscreen-restore");XIconifyWindow(d,a,0);tick();XGetWindowAttributes(d,a,&at);check(at.map_state!=IsViewable,"minimize");XMapWindow(d,a);message(a,"_NET_ACTIVE_WINDOW",2,CurrentTime,0);XGetWindowAttributes(d,a,&at);check(at.map_state==IsViewable,"restore");
XMoveResizeWindow(d,a,90,90,300,180);tick();XGetWindowAttributes(d,a,&at);check(at.width==300&&at.height==180,"resize");Window child;int x,y;XTranslateCoordinates(d,a,root,0,0,&x,&y,&child);
FILE*f=fopen(argv[1],"w");fprintf(f,"ready x=%d y=%d\n",x,y);fclose(f);int key=0,click=0;for(int i=0;i<300&&(!key||!click);i++){while(XPending(d)){XEvent e;XNextEvent(d,&e);if(e.type==KeyPress)key++;if(e.type==ButtonPress)click++;if(e.type==Expose){GC gc=XCreateGC(d,e.xexpose.window,0,0);XSetForeground(d,gc,0xffffff);XDrawString(d,e.xexpose.window,gc,18,40,"Real Linux window - input test",29);XFreeGC(d,gc);}}f=fopen(argv[1],"w");fprintf(f,"ready x=%d y=%d key=%d click=%d\n",x,y,key,click);fclose(f);usleep(100000);}check(key>0,"RFB-keyboard");check(click>0,"RFB-pointer");message(a,"_NET_CLOSE_WINDOW",CurrentTime,2,0);int close_seen=0;for(int i=0;i<20&&!close_seen;i++){while(XPending(d)){XEvent e;XNextEvent(d,&e);if(e.type==ClientMessage&&(Atom)e.xclient.data.l[0]==delete)close_seen=1;}usleep(100000);}check(close_seen,"WM-close-request");XDestroyWindow(d,a);tick();XGetWindowAttributes(d,b,&at);check(at.map_state==IsViewable,"other-window-survives-close");
f=fopen(argv[1],"w");fprintf(f,"PASS checks=%d key=%d click=%d\n",checks,key,click);fclose(f);XDestroyWindow(d,b);XCloseDisplay(d);return 0;}
